using System.Text.RegularExpressions;
using static CF.Core.Setup.DoctorTextPart;

namespace CF.Core.Setup;

/// <summary>Points to the team's configuration for a hook generated by lefthook.</summary>
internal static partial class LefthookAdvice
{
    public const string FileName = "lefthook.yml";

    public const string NotConfirmed = "Doctor could not confirm that lefthook runs CommitFence before a push.";

    private const string _jobName = "- name: commitfence";

    public static string Entry(HookKind kind)
    {
        var hook = kind == HookKind.PrePush ? "pre-push" : "pre-commit";
        var stdin = kind == HookKind.PrePush ? "\n      use_stdin: true" : "";
        return $"{hook}:\n  commands:\n    commitfence:\n      {RunLine(kind)}{stdin}";
    }

    public static DoctorFix Fix(string hookPath, string repositoryFolder, string? configPath, int? jobIndent = null)
    {
        var entry = jobIndent is int indent ? JobEntry(indent) : Entry(HookKind.PrePush);
        var actions = new List<DoctorAction> { new DoctorAction(DoctorActionKind.CopyText, "Copy the lefthook entry", entry) };
        actions.Add(configPath == null
            ? new DoctorAction(DoctorActionKind.OpenFolder, "Open the repository folder", repositoryFolder)
            : new DoctorAction(DoctorActionKind.OpenFile, "Open lefthook.yml", configPath));

        return new DoctorFix(For(hookPath), actions)
        {
            EntryHeading = new DoctorText("Entry to merge into ", CodeText(FileName)),
            EntryHint = jobIndent == null ? MergeHint : JobsHint
        };
    }

    public static DoctorText MergeHint { get; } = new DoctorText("If ", CodeText(FileName), " already has ", CodeText("pre-push:"),
        " and ", CodeText("commands:"), ", paste only the ", CodeText("commitfence:"), " lines under ", CodeText("commands:"),
        ". Only one of its commands can have ", CodeText("use_stdin"), ".");

    private static DoctorText JobsHint { get; } = new DoctorText("Add this entry to the existing ", CodeText("jobs:"),
        " list of ", CodeText("pre-push:"), ". Only one of its jobs can have ", CodeText("use_stdin"), ".");

    private static string RunLine(HookKind kind)
    {
        // Lefthook substitutes arguments verbatim (issue 1613). Double quotes preserve spaces, but the shell still
        // interprets quotes, dollar signs and backticks in a remote name or URL.
        var command = kind == HookKind.PrePush
            ? HookLine.PrePush.Replace("\"$@\"", "\"{1}\" \"{2}\"", StringComparison.Ordinal)
            : HookLine.PreCommit.Replace(" \"$@\"", "", StringComparison.Ordinal);
        return $"run: '{command}'";
    }

    private static string JobEntry(int indent)
    {
        var item = new string(' ', indent);
        return $"{item}{_jobName}\n{item}  {RunLine(HookKind.PrePush)}\n{item}  use_stdin: true";
    }

    // Recognise the entry we offer, including when pasted next to another command or job. Doctor reads
    // configuration and never runs a repository hook. Leave more elaborate configurations to lefthook to interpret.
    public static (bool HasEntry, int? JobIndent) Inspect(string config)
    {
        const string hookName = "pre-push:";
        var lines = DoctorExcerpt.ReadLines(config).Select(line => line.TrimEnd())
            .Where(line => line.Length > 0 && !line.TrimStart().StartsWith('#')).ToList();
        var hookIndex = lines.IndexOf(hookName);
        if(hookIndex < 0 || hookIndex != lines.LastIndexOf(hookName))
            return default;

        var hook = lines.Skip(hookIndex + 1).TakeWhile(line => line.StartsWith(' ')).ToList();
        var (hasJob, jobIndent) = InspectJobs(hook);
        return jobIndent != null ? (hasJob, jobIndent) : (HasCommand(hook), null);
    }

    private static bool HasCommand(List<string> hook)
    {
        var entry = DoctorExcerpt.ReadLines(Entry(HookKind.PrePush));
        var hasCommands = hook.Count > 0 && hook[0] == entry[1] && hook.Count(line => line == entry[1]) == 1
            && hook.Skip(1).All(line => line.StartsWith("    ", StringComparison.Ordinal));
        if(!hasCommands)
            return false;

        var job = hook.IndexOf(entry[2]);
        return job >= 0 && job == hook.LastIndexOf(entry[2])
            && hook.Skip(job + 1).TakeWhile(line => line.StartsWith("      ", StringComparison.Ordinal)).SequenceEqual(entry.Skip(3));
    }

    private static (bool HasEntry, int? JobIndent) InspectJobs(List<string> hook)
    {
        if(hook.Count == 0)
            return default;

        var keyIndent = IndentOf(hook[0]);
        var key = new string(' ', keyIndent) + "jobs:";
        var index = hook.IndexOf(key);
        if(index < 0 || index != hook.LastIndexOf(key))
            return default;

        var jobs = hook.Skip(index + 1).TakeWhile(line => IndentOf(line) > keyIndent || IsJobItem(line, keyIndent)).ToList();
        if(jobs.Count == 0)
            return (false, keyIndent + 2);

        var itemIndent = IndentOf(jobs[0]);
        if(!IsJobItem(jobs[0], itemIndent))
            return default;

        var siblings = hook.Take(index).Concat(hook.Skip(index + 1 + jobs.Count));
        var parallel = new string(' ', keyIndent) + "parallel:";
        var hasEntry = siblings.All(line => line == parallel + " true" || line == parallel + " false") && HasJob(jobs, itemIndent);
        return (hasEntry, itemIndent);
    }

    private static bool HasJob(List<string> jobs, int indent)
    {
        var entry = DoctorExcerpt.ReadLines(JobEntry(indent));
        var index = jobs.IndexOf(entry[0]);
        return index >= 0 && index == jobs.LastIndexOf(entry[0])
            && jobs.Skip(index + 1).TakeWhile(line => IndentOf(line) > indent).SequenceEqual(entry.Skip(1));
    }

    private static int IndentOf(string line)
    {
        return line.Length - line.TrimStart(' ').Length;
    }

    private static bool IsJobItem(string line, int indent)
    {
        return IndentOf(line) == indent && line.AsSpan(indent).StartsWith("- ", StringComparison.Ordinal);
    }

    public static bool HasOverrides(string config)
    {
        return ConfigOverride().IsMatch(config);
    }

    public static bool HasOtherStdin(string config, bool hasEntry)
    {
        return Stdin().Matches(config).Count(match => match.Groups["key"].Success) > (hasEntry ? 1 : 0);
    }

    [GeneratedRegex("^(?:extends|remotes):", RegexOptions.Multiline)]
    private static partial Regex ConfigOverride();

    // Match keys in block and flow mappings. Consume comments and quoted values before looking for another key.
    [GeneratedRegex("""(?:^[ \t]*(?:-[ \t]+)?|[{,][ \t]*)(?<key>use_stdin|'use_stdin'|"use_stdin")[ \t]*:|(?:^|(?<=[ \t]))\#[^\r\n]*|'(?:[^'\r\n]|'')*'|"(?:[^"\\\r\n]|\\[^\r\n])*" """,
        RegexOptions.Multiline | RegexOptions.IgnorePatternWhitespace)]
    private static partial Regex Stdin();

    public static DoctorText For(string hookPath)
    {
        return new DoctorText("Add the CommitFence entry to ", CodeText(FileName), ". lefthook writes ", CodeText(hookPath),
            " from that file, so a line added to the script itself would be written over.");
    }
}
